def paid_grns_get_a_payment(apps, schema_editor):
    """GRNs marked Paid before payments existed: one payment of their full total,
    on the delivery date, so balances and the station's finance start correct."""
    from decimal import Decimal

    from django.db.models import F, Sum

    Receipt = apps.get_model("reception", "CherryReceipt")
    Payment = apps.get_model("reception", "CherryPayment")
    Line = apps.get_model("reception", "CherryReceiptLine")
    totals = dict(
        Line.objects.values("receipt_id")
        .annotate(t=Sum(F("line_amount") + F("transport_cost") + F("commission")))
        .values_list("receipt_id", "t")
    )
    payments = []
    for receipt in Receipt._base_manager.filter(payment_status="PAID"):
        total = totals.get(receipt.pk) or Decimal("0")
        if total <= 0:
            continue
        payments.append(
            Payment(
                receipt_id=receipt.pk,
                paid_on=receipt.received_on,
                amount=total,
                method=receipt.payment_method or "CASH",
                notes="Recorded as paid before payments were tracked.",
                created_by_id=receipt.created_by_id,
                updated_by_id=receipt.created_by_id,
                is_deleted=receipt.is_deleted,
                deleted_at=receipt.deleted_at,
            )
        )
        receipt.amount_paid = total
        receipt.save(update_fields=["amount_paid"])
    Payment._base_manager.bulk_create(payments)


